INSERT INTO `pages` VALUES (1,'privacy-policy','Privacy Policy','<p>MyBaap stores your mobile number and name so you can sign in and watch videos. Playback files stay on the server. We do not sell your personal data.</p>',1,'2026-10-06 12:32:05','2026-10-06 12:32:05'),(2,'terms','Terms of Use','<p>Paid videos need an active subscription. A subscription lasts until its end date. Local payments are a placeholder until a gateway is connected.</p>',1,'2026-10-06 12:32:05','2026-10-06 12:32:05');
